-- Baseline schema generated from the current JPA model at Phase 1 stabilization.
-- This migration includes existing Mission entities so a fresh database matches the deployed model.
create table audit_logs (actor_user_id bigint, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), entity_id varchar(80), entity_type varchar(80) not null, actor_username varchar(100), details varchar(2000), action varchar(40) not null, primary key (id));
create table equipment (available_quantity integer not null, quantity integer not null, reserved_quantity integer not null, created_at timestamp(6), id bigint generated by default as identity, station_id bigint, updated_at timestamp(6), version bigint default 0 not null, name varchar(100) not null, serial_number varchar(100) unique, status varchar(40) not null, type varchar(40) not null, primary key (id));
create table invalidated_tokens (created_at timestamp(6), expiry_time timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6), token_id varchar(255) not null unique, primary key (id));
create table inventory_movements (quantity integer not null, created_at timestamp(6), equipment_id bigint not null, from_station_id bigint, id bigint generated by default as identity, to_station_id bigint, updated_at timestamp(6), actor varchar(100), note varchar(255), type varchar(40) not null, primary key (id));
create table media_assets (created_at timestamp(6), id bigint generated by default as identity, size bigint not null, updated_at timestamp(6), storage_provider varchar(30) not null, linked_entity_id varchar(80), linked_entity_type varchar(80), uploaded_by varchar(100), content_type varchar(120) not null, object_key varchar(500) not null unique, original_name varchar(255) not null, type varchar(40) not null, primary key (id));
create table mission_equipment_reservations (quantity integer not null, released boolean not null, created_at timestamp(6), equipment_id bigint not null, id bigint generated by default as identity, mission_id bigint not null, released_at timestamp(6), updated_at timestamp(6), reserved_by varchar(100), primary key (id));
create table mission_events (actor_id bigint, created_at timestamp(6), id bigint generated by default as identity, mission_id bigint not null, updated_at timestamp(6), description varchar(500), metadata text, event_type varchar(40) not null, new_status varchar(40), old_status varchar(40), primary key (id));
create table mission_media (created_at timestamp(6), id bigint generated by default as identity, media_id bigint not null, mission_id bigint not null, updated_at timestamp(6), uploaded_by bigint, media_role varchar(40) not null, primary key (id), constraint uk_mission_media unique (mission_id, media_id));
create table missions (latitude numeric(10,7), longitude numeric(10,7), operator_accepted boolean not null, requested_date date not null, cancelled_at timestamp(6), completed_at timestamp(6), created_at timestamp(6), customer_id bigint not null, expected_end_time timestamp(6) not null, id bigint generated by default as identity, operator_id bigint, service_id bigint, start_time timestamp(6) not null, station_id bigint, uav_id bigint, updated_at timestamp(6), version bigint default 0 not null, code varchar(30) not null unique, title varchar(180) not null, equipment_condition varchar(500), failure_reason varchar(500), operator_conflict_note varchar(1000), completion_note varchar(2000), description varchar(2000), failure_notes varchar(2000), notes varchar(2000), location_name varchar(255) not null, mission_type varchar(40) not null, priority varchar(40) not null, status varchar(40) not null, primary key (id));
create table permissions (created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), description varchar(255), code varchar(40) not null unique, primary key (id));
create table refresh_tokens (revoked boolean not null, created_at timestamp(6), expiry_date timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6), user_id bigint not null unique, token varchar(128) not null unique, primary key (id));
create table role_template_permissions (created_at timestamp(6), id bigint generated by default as identity, permission_id bigint not null, role_template_id bigint not null, updated_at timestamp(6), primary key (id), unique (role_template_id, permission_id));
create table role_templates (defaults_initialized boolean default false not null, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), name varchar(100) not null, role varchar(40) not null unique, primary key (id));
create table uav_services (active boolean not null, default_duration_minutes integer not null, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), code varchar(60) not null unique, name varchar(160) not null, description varchar(500), primary key (id));
create table uav_stations (latitude float(53), longitude float(53), created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), code varchar(40) not null unique, name varchar(120) not null, address varchar(255), status varchar(40) not null, primary key (id));
create table uav_status_history (created_at timestamp(6), id bigint generated by default as identity, uav_id bigint not null, updated_at timestamp(6), changed_by varchar(100), reason varchar(255), from_status varchar(40), to_status varchar(40) not null, primary key (id));
create table uavs (created_at timestamp(6), id bigint generated by default as identity, last_maintenance_at timestamp(6), station_id bigint, updated_at timestamp(6), model varchar(100) not null, serial_number varchar(100) not null unique, manufacturer varchar(120) not null, status varchar(40) not null, primary key (id));
create table user_permissions (granted boolean not null, created_at timestamp(6), id bigint generated by default as identity, permission_id bigint not null, updated_at timestamp(6), user_id bigint not null, primary key (id), unique (user_id, permission_id));
create table users (failed_attempts integer not null, manual_locked boolean default false not null, created_at timestamp(6), id bigint generated by default as identity, lock_time timestamp(6), updated_at timestamp(6), phone_number varchar(20), username varchar(50) not null unique, full_name varchar(100), zalo_id varchar(100) unique, avatar_url varchar(500), email varchar(255) not null unique, password_hash varchar(255), role varchar(40) not null, status varchar(40) not null, primary key (id));
create index idx_inv_token_expiry on invalidated_tokens (expiry_time);
create index idx_refresh_token_user_id on refresh_tokens (user_id);
